      readTimeMin: 1,
      content: `DLACZEGO SYSTEM BOI SIĘ TWÓRCÓW

System nie boi się buntowników.
Buntowników da się zmęczyć.

Nie boi się krytyków.
Krytyków da się zagadać.

System boi się twórców,
bo twórcy nie walczą z nim bezpośrednio.

Oni wychodzą z gry.

Człowiek, który tworzy,
nie jest już tylko konsumentem bólu.
Nie jest tylko nośnikiem zmęczenia.

Zaczyna generować sens.

A sens jest groźny.

Bo sens sprawia, że:

nie potrzebujesz znieczulenia

nie potrzebujesz kasyna

nie potrzebujesz narracji „jakoś to będzie"

Twórca nie pyta systemu o pozwolenie.
On nie prosi o akceptację.

On buduje równolegle.

System tego nie umie zatrzymać,
bo nie ma na to procedury.

Nie da się zakazać myślenia.
Nie da się opodatkować woli.
Nie da się skatalogować prawdy przeżytej.

Dlatego system woli,
żebyś był zmęczony niż zły.
Zajęty niż świadomy.
Znieczulony niż obecny.

A kiedy przestajesz grać,
on nie ma już dla ciebie oferty.

To jest prawdziwe wyjście z matrycy.
Nie ucieczka.
Nie bunt.

Niezależna architektura sensu.`
