      readTimeMin: 1,
      content: `Nie piszę tej książki, żeby cię zainspirować.
Piszę ją, bo takich ludzi jak ja nikt nie opisuje.

Piszę ją dla tych, którzy nauczyli się śmiać z zamkniętymi ustami.
Dla tych, którzy przestali podnosić głowę w tłumie.
Dla tych, którzy potrafią zapierdalać dwanaście godzin dziennie,
a nie potrafią powiedzieć obcej osobie „cześć".

Mam sto tysięcy długu.
Nie mam przednich zębów.
Przez dziewięć miesięcy nie wiedziałem, czy mój syn jeszcze mnie pamięta.

To nie jest metafora.
To jest stan faktyczny.

Pięć lat bez jedynek.
Pięć lat, w których ciało uczy się nowych zasad przetrwania.
Nie otwieraj ust.
Nie śmiej się głośno.
Nie patrz ludziom w oczy za długo.
Nie dawaj im pretekstu.

System nazywa to „problem estetyczny".
Ja nazywam to społeczną amputacją.

Nagle jesteś mniej widzialny.
Nagle rozmowy skracają się same.
Nagle czujesz, że każdy kontakt to egzamin.

Nie dlatego, że jesteś gorszy.
Tylko dlatego, że nie pasujesz do katalogu uśmiechów.

A teraz ironia.

Byłem majstrem.
Przez trzy lata prowadziłem ludzi.
Decydowałem. Organizowałem. Odpowiadałem za robotę.

Bez zębów.

W pracy byłem dowódcą.
Na ulicy byłem cieniem.

To jest schizofrenia systemowa, o której się nie mówi.

Możesz być kompetentny.
Możesz być silny.
Możesz być potrzebny.

I jednocześnie bać się, że ktoś zobaczy twoje usta.

Ta książka nie jest o zębach.
Jest o tym, co brak robi z psychiką.
Jak rodzi wstyd.
Jak tworzy izolację.
Jak zamienia ludzi w samotne wyspy.

Jeśli tu jesteś — to znaczy, że coś z tego znasz.

Nazywam się Maciek.
Jestem Tabuseeker.
I zaczynamy od prawdy.

---`
